import {WORKSHOP_SKINS} from './zones.js';
export const PROP_SKINS=['tuned','luxury','van','classic','cash','heal','charge','upgrade','map','key','bag','pizza','sofa','bed','desk','terminal'];
export const DETAIL_SKINS=['olive','forklift','cutter','bee','church','fountain','reception','arch','tires','pipes','server','diamonds','lectern','workbench','birthday','bunting'];
export const ENV_SKINS=['greek','country','villa','garage','marble','parquet','sewer','concrete'];
export const SKIN_NAMES={olive:'Ulivo greco',forklift:'Muletto industriale',cutter:'Macchina dei diamanti',bee:'Prototipo APE',church:'Chiesa di Roma',fountain:'Fontana romana',reception:'Reception di lusso',arch:'Arco in pietra',tires:'Pneumatici da gara',pipes:'Valvole e tubature',server:'Server riservato',diamonds:'Valigia di diamanti',lectern:'Leggio dell’assemblea',workbench:'Banco di Luca',birthday:'Trenta candeline',bunting:'Decorazioni del Giubileo',tuned:'Spit Custom',luxury:'Auto di lusso',van:'Furgone della banda',classic:'Muscle car',cash:'Cassa denaro',heal:'Kit medico',charge:'Cassa energia',upgrade:'Cassa tecnologia',map:'Mappa da esplorare',key:'Chiave e pass',bag:'Documenti e bagagli',pizza:'Consegna bollente',sofa:'Divano del salone',bed:'Letto della camera',desk:'Scrivania dello studio',terminal:'Terminale',greek:'Casa greca',country:'Casa piemontese',villa:'Villa',garage:'Officina',marble:'Salone in marmo',parquet:'Camera in parquet',sewer:'Sotterranei',concrete:'Pavimento officina'};
export function addGridFrames(scene,key,names,cols,rows){const texture=scene.textures.get(key),w=texture.source[0].width/cols,h=texture.source[0].height/rows;names.forEach((name,i)=>texture.add(name,0,Math.round(i%cols*w),Math.round(Math.floor(i/cols)*h),Math.round((i%cols+1)*w)-Math.round(i%cols*w),Math.round((Math.floor(i/cols)+1)*h)-Math.round(Math.floor(i/cols)*h)));}
export const CELEBRATION_SKINS=['child-click','child-paula','child-nico','click','ted','spit','andy','bruce','carlitos','ale','luca','anna','paula','nico','click-suit','backpack'];
export const LANDSCAPE_SKINS=['coast-house','depot','ruin-gate','bus-stop','manor','estate-garage','hedge','garden','grass','cobble','villa-marble','villa-wood'];
export function registerWorldSkins(scene){addGridFrames(scene,'workshop',WORKSHOP_SKINS,4,2);addGridFrames(scene,'celebration',CELEBRATION_SKINS,4,4);addGridFrames(scene,'landscape',LANDSCAPE_SKINS,4,3);addGridFrames(scene,'details',DETAIL_SKINS,4,4);addGridFrames(scene,'props',PROP_SKINS,4,4);addGridFrames(scene,'environment',ENV_SKINS,4,2);}
export function prop(scene,skin,x,y,size=65,depth=y){return scene.add.image(x,y,WORKSHOP_SKINS.includes(skin)?'workshop':skin==='backpack'?'celebration':LANDSCAPE_SKINS.includes(skin)?'landscape':DETAIL_SKINS.includes(skin)?'details':'props',skin).setOrigin(.5,.9).setDisplaySize(size,size).setDepth(depth);}
export function floor(scene,skin,x,y,w,h){const texture=LANDSCAPE_SKINS.includes(skin)?'landscape':'environment';const view=scene.add.tileSprite(x,y,w,h,texture,skin).setOrigin(0).setDepth(1);const frame=scene.textures.get(texture).get(skin);view.setTileScale(120/frame.width);return view;}
export function pointSkin(point){if(point.skin)return point.skin;const id=point.id.toLowerCase();if(/bag|photo|dossier/.test(id))return 'bag';if(/map|foot|depot/.test(id))return 'map';if(/car|key|fence|entry|story/.test(id))return 'key';return 'terminal';}
